        },
        {
          "@type": "Question",
          "name": "Is pickup available in Bakersfield?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Pickup is available for qualifying commercial volumes in Bakersfield and throughout Kern County. Scheduling depends on equipment type, quantity, loading conditions, timing, and service requirements. Organizations can contact STS to discuss the computers, servers, displays, networking equipment, mobile devices, or mixed electronics they need to retire."
          }
        },
        {
          "@type": "Question",
          "name": "What happens after electronics are collected?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Assets are inventoried as appropriate, transported through a documented chain of custody, and routed for data handling and material recovery. Reporting options vary by project scope and can include certificates or disposition documentation for qualified Bakersfield equipment-recycling projects."
          }
        },
        {
          "@type": "Question",
          "name": "Do you recycle computers, servers, and networking equipment?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. STS handles computers, laptops, servers, monitors, printers, networking equipment, mobile devices, copiers, accessories, and other business electronics. Large mixed loads from Bakersfield and Kern County organizations can be reviewed during the quote and scheduling process."
          }
        }
